// Get the current item data
const d = $input.item.json;

// --- Layer 1: Structure Check ---
// Ensure the object actually contains data
if (!d || Object.keys(d).length === 0) {
  return {
    ...d,
    _isSanityCheckPassed: false,
    _rejectionReason: "Empty Object"
  };
}

// --- Layer 2: Required Field Check ---
// Check if Email and Name exist and aren't placeholders
const hasEmail = d.email && d.email.includes('@');
const hasName = d.name && d.name.length > 2 && d.name.toLowerCase() !== 'test';

// --- Layer 3: Formatting Check ---
// Flag common "junk" indicators
const isJunkEmail = d.email ? (d.email.includes('example.com') || d.email.includes('test.com')) : true;
const isGenericName = d.name ? (d.name.toLowerCase().includes('user') || d.name.toLowerCase().includes('admin')) : true;

// --- Final Decision Engine ---
const isSanityCheckPassed = hasEmail && hasName && !isJunkEmail && !isGenericName;

// Determine the primary reason for failure (if any)
let reason = "";
if (!hasEmail) reason = "Invalid/Missing Email";
else if (!hasName) reason = "Invalid/Short Name";
else if (isJunkEmail) reason = "Junk Domain Found";
else if (isGenericName) reason = "Generic/Bot Name";

return {
  ...d, // Keep all your original data
  _isSanityCheckPassed: isSanityCheckPassed,
  _rejectionReason: reason
};

